import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;

public class ReportGeneratorServlet extends HttpServlet {

    private static final String TEMPLATE_DIR = "/opt/reports/templates/";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String templateName = req.getParameter("template");
        String outputFormat = req.getParameter("format");
        String dataSourceId = req.getParameter("dsid");

        // Validate template name - only alphanumeric and hyphens
        if (templateName == null || !templateName.matches("[a-zA-Z0-9\\-]+")) {
            resp.sendError(400, "Invalid template name");
            return;
        }

        // Load template
        String templatePath = TEMPLATE_DIR + templateName + ".rpt";
        String templateContent = new String(
            java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(templatePath)));

        // Build substitution map from request parameters
        Map<String, String> valuesMap = new HashMap<>();
        Enumeration<String> paramNames = req.getParameterNames();
        while (paramNames.hasMoreElements()) {
            String param = paramNames.nextElement();
            if (param.startsWith("field_")) {
                String fieldName = param.substring(6);
                valuesMap.put(fieldName, req.getParameter(param));
            }
        }

        // Perform template substitution using Apache Commons Text
        StringSubstitutor sub = new StringSubstitutor(valuesMap);
        String rendered = sub.replace(templateContent);

        // Execute rendered content as SQL report query
        try (Connection conn = getDataSource(dataSourceId).getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(rendered)) {

            StringBuilder result = new StringBuilder();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            // CSV output
            for (int i = 1; i <= cols; i++) {
                result.append(meta.getColumnName(i));
                if (i < cols) result.append(",");
            }
            result.append("\n");

            while (rs.next()) {
                for (int i = 1; i <= cols; i++) {
                    String val = rs.getString(i);
                    // Escape CSV values
                    if (val != null && (val.contains(",") || val.contains("\""))) {
                        val = "\"" + val.replace("\"", "\"\"") + "\"";
                    }
                    result.append(val != null ? val : "");
                    if (i < cols) result.append(",");
                }
                result.append("\n");
            }

            resp.setContentType("text/csv");
            resp.setHeader("Content-Disposition", 
                "attachment; filename=report_" + templateName + ".csv");
            resp.getWriter().write(result.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    private javax.sql.DataSource getDataSource(String dsid) {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup(
                "java:comp/env/jdbc/" + (dsid != null ? dsid : "reporting"));
        } catch (javax.naming.NamingException e) {
            throw new RuntimeException("DataSource not found", e);
        }
    }
}
